<script setup lang="ts">
import DecorationPreview from '../../components/console/DecorationPreview.vue'
import type {DecorationLink,DecorationApplicationAssets,DecorationApplicationComponent,DecorationScheme} from '../../utils/decoration'
definePageMeta({layout:false})
const auth=useApi('tenant'),route=useRoute(),token=String(route.params.token),base='/public/decoration-previews/'+encodeURIComponent(token)
const {data,error}=await useAsyncData('decoration-preview:'+token,async()=>{const result=await auth.api<{assets?:DecorationApplicationAssets;components?:DecorationApplicationComponent[];name:string;scheme:DecorationScheme;page:'home'|'profile'}>(base);return result})
const page=ref<'home'|'profile'>(data.value?.page||'home'),notice=ref('')
useHead(()=>({title:data.value?data.value.scheme[page.value].title+' · '+data.value.name+'预览':'预览已失效',meta:[{name:'robots',content:'noindex,nofollow'},{name:'referrer',content:'no-referrer'}]}))
function navigate(target:DecorationLink){if(target==='home'||target==='profile'){page.value=target;notice.value=''}else if(target)notice.value='当前为草稿预览，保存后可从客户端入口使用此功能'}
</script>
<template><div class="public-decoration-preview"><DecorationPreview :assets="data?.assets" :components="data?.components" v-if="data" :scheme="data.scheme" :page="page" :image-url="(id:string)=>'/api/v1'+base+'/images/'+encodeURIComponent(id)" @navigate="navigate"/><div v-else class="preview-unavailable"><UIcon name="i-lucide-clock-3"/><h1>预览暂不可用</h1><p>{{error?.message||'请返回编辑器重新生成预览链接'}}</p></div><div v-if="notice" class="preview-notice-message" @click="notice=''">{{notice}}</div></div></template>
<style scoped>.public-decoration-preview{position:relative;height:100dvh;width:min(480px,100%);margin:auto;box-shadow:0 0 24px #3341550a}.public-decoration-preview :deep(.decoration-preview){height:100%;min-height:0;border:0;border-radius:0;box-shadow:none;display:flex;flex-direction:column}.public-decoration-preview :deep(.preview-content){overflow:auto;min-height:0;flex:1}.public-decoration-preview :deep(.preview-title),.public-decoration-preview :deep(.preview-navigation){flex-shrink:0}.preview-unavailable{height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:14px;padding:24px;background:#f5f7fb;color:#334155;text-align:center}.preview-unavailable>.iconify{font-size:32px;color:#94a3b8}.preview-unavailable h1{font-size:20px;font-weight:600}.preview-unavailable p{font-size:13px;line-height:1.7}.preview-notice-message{position:absolute;bottom:76px;left:50%;transform:translateX(-50%);background:#0f172acc;color:white;border-radius:8px;padding:12px 20px;font-size:12px;line-height:1.6;max-width:calc(100% - 32px);width:max-content;text-align:center}@media(max-width:600px){.public-decoration-preview{width:100%;height:100dvh}}</style>
